package com.vynedam.stockai.controller;
import com.vynedam.stockai.dto.WarehouseDtos.*; import com.vynedam.stockai.model.Warehouse; import com.vynedam.stockai.service.WarehouseService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/warehouses") public class WarehouseController {private final WarehouseService service;public WarehouseController(WarehouseService s){service=s;}@GetMapping List<Warehouse>list(){return service.list();}@GetMapping("/{id}") Warehouse get(@PathVariable String id){return service.get(id);}@PostMapping@PreAuthorize("hasAnyRole('SUPER_ADMIN','PLANT_MANAGER','STORE_MANAGER')")ResponseEntity<Warehouse>create(@Valid@RequestBody WarehouseRequest r){return ResponseEntity.status(201).body(service.create(r));}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','PLANT_MANAGER','STORE_MANAGER')")Warehouse update(@PathVariable String id,@Valid@RequestBody WarehouseRequest r){return service.update(id,r);}@PatchMapping("/{id}/active")@PreAuthorize("hasAnyRole('SUPER_ADMIN','PLANT_MANAGER')")Warehouse active(@PathVariable String id,@RequestParam boolean value){return service.setActive(id,value);}@PutMapping("/{id}/staff")@PreAuthorize("hasAnyRole('SUPER_ADMIN','PLANT_MANAGER','STORE_MANAGER')")ResponseEntity<Void>assignStaff(@PathVariable String id,@Valid@RequestBody StaffAssignmentRequest r){service.assignStaff(id,r);return ResponseEntity.noContent().build();}}
